CREATE TABLE IF NOT EXISTS public.sales (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, vehicle_id uuid NOT NULL REFERENCES public.vehicles(id) ON DELETE RESTRICT, driver_id uuid NOT NULL REFERENCES public.drivers(id) ON DELETE RESTRICT, sale_type text NOT NULL CHECK (sale_type IN ('CASH','HIRE_PURCHASE')), status text NOT NULL DEFAULT 'DRAFT', cash_price numeric NOT NULL CHECK (cash_price >= 0), sale_price numeric NOT NULL CHECK (sale_price >= 0), deposit_amount numeric NOT NULL DEFAULT 0 CHECK (deposit_amount >= 0), financed_amount numeric NOT NULL DEFAULT 0 CHECK (financed_amount >= 0), currency text NOT NULL DEFAULT 'KES', contract_start_date date, notes text, created_by uuid, approved_by uuid, approved_at timestamptz, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());